    for (ch in s) {
        when (ch) {
            '0', '1' -> {
                // ignore
            }
            '2', '3', '5', '7' -> {
                resultDigits.add(ch)
            }
            '4' -> {
                // 4! = 3! * 2! * 2! -> digits 3,2,2
                resultDigits.add('3')
                resultDigits.add('2')
                resultDigits.add('2')
            }
            '6' -> {
                // 6! = 5! * 3! -> digits 5,3
                resultDigits.add('5')
                resultDigits.add('3')
            }
            '8' -> {
                // 8! = 7! * 2! * 2! * 2! -> digits 7,2,2,2
                resultDigits.add('7')
                resultDigits.add('2')
                resultDigits.add('2')
                resultDigits.add('2')
            }
            '9' -> {
                // 9! = 7! * 3! * 3! * 2! -> digits 7,3,3,2
                resultDigits.add('7')
                resultDigits.add('3')
                resultDigits.add('3')
                resultDigits.add('2')
            }
        }
    }

    resultDigits.sortDescending()
    println(resultDigits.joinToString(""))
